async function getBase64FromPublic(relativePath: string) {
  const filePath = path.join(process.cwd(), "public", relativePath);
  const fileData = await fs.readFile(filePath);
  return fileData.toString("base64");
}

function drawFullWidthSectionHeading(
  title: string,
  page: PDFPage,
  font: PDFFont,
  yPosRef: { value: number },
  leftMargin: number,
  rightMargin: number,
  sectionFontSize: number,
  pageWidth: number
) {
  const textHeight = font.heightAtSize(sectionFontSize);

  const paddingY = 8;
  const paddingX = 10;

  // Full width rectangle (respecting margins)
  const rectX = leftMargin;
  const rectY = yPosRef.value - textHeight - paddingY;
  const rectW = pageWidth - leftMargin - rightMargin;
  const rectH = textHeight + paddingY * 2;

  // Draw full-width gray strip
  page.drawRectangle({
    x: rectX,
    y: rectY,
    width: rectW,
    height: rectH,
    color: rgb(0.9, 0.9, 0.9),
  });

  // Draw heading text inside the strip
  page.drawText(title, {
    x: rectX + paddingX,
    y: rectY + paddingY,
    size: sectionFontSize,
    font,
    color: rgb(0, 0, 0),
  });

  // Update y-position
  yPosRef.value = rectY - 20;
}

