const handleRejectionReason = async (
  rejectionReason: string,
  id: any,
  index: number
) => {
  setLoading(true);
  if (!queries[index].leadQualityByReviewer) {
    toast({
      description: "Please select lead quality first",
      variant: "destructive",
    });
    setLoading(false);
    return;
  }
  try {
    const oldStatus = queries[index].leadStatus || "fresh";
    const response = await axios.post("/api/sales/rejectionReason", {
      id,
      rejectionReason,
    });
    toast({
      description: "Rejection reason saved succefully",
    });
    queries[index].rejectionReason = rejectionReason;
    if (response.data?.data) {
      emitDispositionChange(response.data.data, oldStatus, "rejected");
    }
    setLoading(false);
  } catch (error: any) {
    setLoading(false);
    toast({
      description: "Error occurred while updating status",
    });
  }
};

