  // Try reminder field first (new format)
  if (query?.reminder) {
    const d = new Date(query.reminder);
    if (!isNaN(d.getTime())) return d;
  }
  // Fallback to reason field (old format - stored as ISO string)
  if (query?.reason) {
    const d = new Date(query.reason);
    if (!isNaN(d.getTime())) return d;
  }
  return null;
};

